import{_ as p,a0 as r,w as o,s as l,I as t,x as s,a1 as e,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何使用 GParted 實用工具縮放根分區 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 GParted 實用工具縮放根分區 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 GParted 實用工具縮放根分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 GParted 實用工具縮放根分區 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20180416 How To Resize Active-Primary root Partition Using GParted Utility","title":"如何使用 GParted 實用工具縮放根分區","tag":"201906","desc":""},"relativePath":"201906/20180416 How To Resize Active-Primary root Partition Using GParted Utility.md","filePath":"[post].md"}'),g={name:"201906/20180416 How To Resize Active-Primary root Partition Using GParted Utility.md"};function u(c,a,h,m,w,y){const i=r("Link");return o(),l("div",null,[a[17]||(a[17]=t("h1",{id:"如何使用-gparted-實用工具縮放根分區",tabindex:"-1"},[s("如何使用 GParted 實用工具縮放根分區 "),t("a",{class:"header-anchor",href:"#如何使用-gparted-實用工具縮放根分區","aria-label":"Permalink to “如何使用 GParted 實用工具縮放根分區”"},"​")],-1)),a[18]||(a[18]=t("p",null,"今天，我們將討論磁盤分區。這是 Linux 中的一個好話題。這允許用户來重新調整在 Linux 中的活動 root 分區。",-1)),a[19]||(a[19]=t("p",null,"在這篇文章中，我們將教你如何使用 GParted 縮放在 Linux 上的活動根分區。",-1)),a[20]||(a[20]=t("p",null,"比如説，當我們安裝 Ubuntu 操作系統時，並沒有恰當地配置，我們的系統僅有 30 GB 磁盤。我們需要安裝另一個操作系統，因此我們想在其中製作第二個分區。",-1)),a[21]||(a[21]=t("p",null,"雖然不建議重新調整活動分區。然而，我們要執行這個操作，因為沒有其它方法來釋放系統分區。",-1)),a[22]||(a[22]=t("blockquote",null,[t("p",null,"注意：在執行這個動作前，確保你備份了重要的數據，因為如果一些東西出錯（例如，電源故障或你的系統重啓)，你可以得以保留你的數據。")],-1)),a[23]||(a[23]=t("h3",{id:"gparted-是什麼",tabindex:"-1"},[s("Gparted 是什麼 "),t("a",{class:"header-anchor",href:"#gparted-是什麼","aria-label":"Permalink to “Gparted 是什麼”"},"​")],-1)),t("p",null,[e(i,{href:"https://gparted.org/"},{default:n(()=>[...a[0]||(a[0]=[s("GParted",-1)])]),_:1}),a[1]||(a[1]=s(" 是一個自由的分區管理器，它使你能夠縮放、複製和移動分區，而不丟失數據。通過使用 GParted 的 Live 可啓動鏡像，我們可以使用 GParted 應用程序的所有功能。GParted Live 可以使你能夠在 GNU/Linux 以及其它的操作系統上使用 GParted，例如，Windows 或 Mac OS X 。",-1))]),a[24]||(a[24]=d(`<h4 id="_1-使用-df-命令檢查磁盤空間利用率" tabindex="-1">1) 使用 df 命令檢查磁盤空間利用率 <a class="header-anchor" href="#_1-使用-df-命令檢查磁盤空間利用率" aria-label="Permalink to “1) 使用 df 命令檢查磁盤空間利用率”">​</a></h4><p>我只是想使用 <code>df</code> 命令向你顯示我的分區。<code>df</code> 命令輸出清楚地表明我僅有一個分區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h</span></span>
<span class="line"><span>Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/sda1        30G  3.4G 26.2G  16% /</span></span>
<span class="line"><span>none            4.0K     0  4.0K   0% /sys/fs/cgroup</span></span>
<span class="line"><span>udev            487M  4.0K  487M   1% /dev</span></span>
<span class="line"><span>tmpfs           100M  844K   99M   1% /run</span></span>
<span class="line"><span>none            5.0M     0  5.0M   0% /run/lock</span></span>
<span class="line"><span>none            498M  152K  497M   1% /run/shm</span></span>
<span class="line"><span>none            100M   52K  100M   1% /run/user</span></span></code></pre></div><h4 id="_2-使用-fdisk-命令檢查磁盤分區" tabindex="-1">2) 使用 fdisk 命令檢查磁盤分區 <a class="header-anchor" href="#_2-使用-fdisk-命令檢查磁盤分區" aria-label="Permalink to “2) 使用 fdisk 命令檢查磁盤分區”">​</a></h4><p>我將使用 <code>fdisk</code> 命令驗證這一點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fdisk -l</span></span>
<span class="line"><span>[sudo] password for daygeek:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sda: 33.1 GB, 33129218048 bytes</span></span>
<span class="line"><span>255 heads, 63 sectors/track, 4027 cylinders, total 64705504 sectors</span></span>
<span class="line"><span>Units = sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disk identifier: 0x000473a3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Device Boot      Start         End      Blocks   Id  System</span></span>
<span class="line"><span>/dev/sda1   *        2048    62609407    31303680   83  Linux</span></span>
<span class="line"><span>/dev/sda2        62611454    64704511     1046529    5  Extended</span></span>
<span class="line"><span>/dev/sda5        62611456    64704511     1046528   82  Linux swap / Solaris</span></span></code></pre></div><h4 id="_3-下載-gparted-live-iso-鏡像" tabindex="-1">3) 下載 GParted live ISO 鏡像 <a class="header-anchor" href="#_3-下載-gparted-live-iso-鏡像" aria-label="Permalink to “3) 下載 GParted live ISO 鏡像”">​</a></h4><p>使用下面的命令來執行下載 GParted live ISO。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget https://downloads.sourceforge.net/gparted/gparted-live-0.31.0-1-amd64.iso</span></span></code></pre></div><h4 id="_4-使用-gparted-live-安裝介質啓動你的系統" tabindex="-1">4) 使用 GParted Live 安裝介質啓動你的系統 <a class="header-anchor" href="#_4-使用-gparted-live-安裝介質啓動你的系統" aria-label="Permalink to “4) 使用 GParted Live 安裝介質啓動你的系統”">​</a></h4><p>使用 GParted Live 安裝介質（如燒錄的 CD/DVD 或 USB 或 ISO 鏡像）啓動你的系統。你將獲得類似於下面屏幕的輸出。在這裏選擇 “GParted Live (Default settings)” ，並敲擊回車按鍵。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-1.png" alt=""></p><h4 id="_5-鍵盤選擇" tabindex="-1">5) 鍵盤選擇 <a class="header-anchor" href="#_5-鍵盤選擇" aria-label="Permalink to “5) 鍵盤選擇”">​</a></h4><p>默認情況下，它選擇第二個選項，按下回車即可。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-2.png" alt=""></p><h4 id="_6-語言選擇" tabindex="-1">6) 語言選擇 <a class="header-anchor" href="#_6-語言選擇" aria-label="Permalink to “6) 語言選擇”">​</a></h4><p>默認情況下，它選擇 “33” 美國英語，按下回車即可。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-3.png" alt=""></p><h4 id="_7-模式選擇-圖形用户界面或命令列" tabindex="-1">7) 模式選擇（圖形用户界面或命令列) <a class="header-anchor" href="#_7-模式選擇-圖形用户界面或命令列" aria-label="Permalink to “7) 模式選擇（圖形用户界面或命令列)”">​</a></h4><p>默認情況下，它選擇 “0” 圖形用户界面模式，按下回車即可。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-4.png" alt=""></p><h4 id="_8-加載-gparted-live-屏幕" tabindex="-1">8) 加載 GParted Live 屏幕 <a class="header-anchor" href="#_8-加載-gparted-live-屏幕" aria-label="Permalink to “8) 加載 GParted Live 屏幕”">​</a></h4><p>現在，GParted Live 屏幕已經加載，它顯示我以前創建的分區列表。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-5.png" alt=""></p><h4 id="_9-如何重新調整根分區大小" tabindex="-1">9) 如何重新調整根分區大小 <a class="header-anchor" href="#_9-如何重新調整根分區大小" aria-label="Permalink to “9) 如何重新調整根分區大小”">​</a></h4><p>選擇你想重新調整大小的根分區，在這裏僅有一個分區，所以我將編輯這個分區以便於安裝另一個操作系統。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-6.png" alt=""></p><p>為做到這一點，按下 “Resize/Move” 按鈕來重新調整分區大小。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-7.png" alt=""></p><p>現在，在第一個框中輸入你想從這個分區中取出的大小。我將索要 “10GB”，所以，我添加 “10240MB”，並讓該對話框的其餘部分為默認值，然後點擊 “Resize/Move” 按鈕。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-8.png" alt=""></p><p>它將再次要求你確認重新調整分區的大小，因為你正在編輯活動的系統分區，然後點擊 “Ok”。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-9.png" alt=""></p><p>分區從 30GB 縮小到 20GB 已經成功。也顯示 10GB 未分配的磁盤空間。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-10.png" alt=""></p><p>最後點擊 “Apply” 按鈕來執行下面剩餘的操作。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-11.png" alt=""></p><p><code>e2fsck</code> 是一個文件系統檢查實用程序，自動修復文件系統中與 HDD 相關的壞扇道、I/O 錯誤。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-12.png" alt=""></p><p><code>resize2fs</code> 程序將重新調整 ext2、ext3 或 ext4 文件系統的大小。它可以被用於擴大或縮小一個位於設備上的未掛載的文件系統。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-13.png" alt=""></p><p><code>e2image</code> 程序將保存位於設備上的關鍵的 ext2、ext3 或 ext4 文件系統的元數據到一個指定文件中。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-14.png" alt=""></p><p>所有的操作完成，關閉對話框。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-15.png" alt=""></p><p>現在，我們可以看到未分配的 “10GB” 磁盤分區。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-16.png" alt=""></p><p>重啓系統來檢查這一結果。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2014/08/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility-17.png" alt=""></p><h4 id="_10-檢查剩餘空間" tabindex="-1">10) 檢查剩餘空間 <a class="header-anchor" href="#_10-檢查剩餘空間" aria-label="Permalink to “10) 檢查剩餘空間”">​</a></h4><p>重新登錄系統，並使用 <code>fdisk</code> 命令來查看在分區中可用的空間。是的，我可以看到這個分區上未分配的 “10GB” 磁盤空間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo parted /dev/sda print free</span></span>
<span class="line"><span>[sudo] password for daygeek: </span></span>
<span class="line"><span>Model: ATA VBOX HARDDISK (scsi)</span></span>
<span class="line"><span>Disk /dev/sda: 32.2GB</span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B</span></span>
<span class="line"><span>Partition Table: msdos</span></span>
<span class="line"><span>Disk Flags: </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number  Start   End     Size    Type     File system  Flags</span></span>
<span class="line"><span>        32.3kB  10.7GB  10.7GB           Free Space</span></span>
<span class="line"><span> 1      10.7GB  32.2GB  21.5GB  primary  ext4         boot</span></span></code></pre></div><hr>`,53)),t("p",null,[a[3]||(a[3]=s("via: ",-1)),e(i,{href:"https://www.2daygeek.com/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility/"},{default:n(()=>[...a[2]||(a[2]=[s("https://www.2daygeek.com/how-to-resize-active-primary-root-partition-in-linux-using-gparted-utility/",-1)])]),_:1})]),t("p",null,[a[8]||(a[8]=s("作者：",-1)),e(i,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...a[4]||(a[4]=[s("Magesh Maruthamuthu",-1)])]),_:1}),a[9]||(a[9]=s(" 譯者：",-1)),e(i,{href:"https://github.com/robsean"},{default:n(()=>[...a[5]||(a[5]=[s("robsean",-1)])]),_:1}),a[10]||(a[10]=s(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...a[6]||(a[6]=[s("wxy",-1)])]),_:1}),a[11]||(a[11]=s(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[7]||(a[7]=[s("lujun9972",-1)])]),_:1})]),t("p",null,[a[14]||(a[14]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[12]||(a[12]=[s("LCTT",-1)])]),_:1}),a[15]||(a[15]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...a[13]||(a[13]=[s("Linux中國",-1)])]),_:1}),a[16]||(a[16]=s(" 榮譽推出",-1))])])}const v=p(g,[["render",u]]);export{b as __pageData,v as default};
